import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        dist = float(data)
    except ValueError:
        return

    if dist <= 3:
        charge = 0.0
    elif dist <= 10:
        charge = dist * 10
    else:
        charge = 100 + (dist - 10) * 8

    print(f"Delivery Charge: ₹{charge:.2f}")

if __name__ == "__main__":
    main()
